seq-sum:
: main
  (forall ρ; ρ xs:Seq Int^many -- ρ total:Int^many)
  locals { xs } { 0 0 xs call sum-helper };

: sum-helper
  (forall ρ; ρ sum:Int^many i:Int^many xs:Seq Int^many -- ρ result:Int^many)
  locals { sum i xs } {
    i xs prim seq-int.len prim <
    [
      xs i prim seq-int.at sum prim +
      1 i prim +
      xs
      call sum-helper
    ]
    [ sum ]
    if
  };

seq-max:
: main
  (forall ρ; ρ xs:Seq Int^many -- ρ largest:Int^many)
  locals { xs } {
    xs 0 prim seq-int.at
    1
    xs
    call max-helper
  };

: max-helper
  (forall ρ; ρ max:Int^many i:Int^many xs:Seq Int^many -- ρ result:Int^many)
  locals { max i xs } {
    i xs prim seq-int.len prim <
    [
      xs i prim seq-int.at max
      locals { elem prev-max } {
        prev-max elem prim <
        [ elem ]
        [ prev-max ]
        if
      }
      i 1 prim +
      xs
      call max-helper
    ]
    [ max ]
    if
  };

count-below:
: main
  (forall ρ; ρ xs:Seq Int^many k:Int^many -- ρ count:Int^many)
  locals { xs k } {
    0
    0
    xs
    k
    call count-loop
  };

: count-loop
  (forall ρ; ρ count:Int^many i:Int^many xs:Seq Int^many k:Int^many -- ρ result:Int^many)
  locals { count i xs k } {
    i xs prim seq-int.len prim <
    [
      xs i prim seq-int.at
      locals { elem } {
        elem k prim <
        [ count 1 prim + ]
        [ count ]
        if
      }
      i 1 prim +
      xs
      k
      call count-loop
    ]
    [ count ]
    if
  };

index-of:
: main
  (forall ρ; ρ xs:Seq Int^many x:Int^many -- ρ index:Int^many)
  locals { xs x } {
    0
    xs
    x
    call index-loop
  };

: index-loop
  (forall ρ; ρ i:Int^many xs:Seq Int^many x:Int^many -- ρ final-index:Int^many)
  locals { i xs x } {
    i xs prim seq-int.len prim <
    [
      xs i prim seq-int.at x prim =
      [
        i
      ]
      [
        i 1 prim +
        xs
        x
        call index-loop
      ]
      if
    ]
    [ -1 ]
    if
  };

reverse:
: main
  (forall ρ; ρ xs:Seq Int^many -- ρ reversed:Seq Int^many)
  locals { xs } {
    prim seq-int.empty
    xs prim seq-int.len 1 prim -
    xs
    call reverse-loop
  };

: reverse-loop
  (forall ρ; ρ result:Seq Int^many i:Int^many xs:Seq Int^many -- ρ reversed:Seq Int^many)
  locals { result i xs } {
    i 0 prim <
    prim not
    [
      xs i prim seq-int.at
      result prim seq-int.push
      i 1 prim -
      xs
      call reverse-loop
    ]
    [ result ]
    if
  };

prefix-sums:
: main
  (forall ρ; ρ xs:Seq Int^many -- ρ sums:Seq Int^many)
  locals { xs } {
    prim seq-int.empty
    0
    0
    xs
    call prefix-loop
  };

: prefix-loop
  (forall ρ; ρ result:Seq Int^many sum:Int^many i:Int^many xs:Seq Int^many -- ρ prefix-sums:Seq Int^many)
  locals { result sum i xs } {
    i xs prim seq-int.len prim <
    [
      xs i prim seq-int.at sum prim +
      locals { new-sum } {
        new-sum
        result prim seq-int.push
        new-sum
        i 1 prim +
        xs
        call prefix-loop
      }
    ]
    [ result ]
    if
  };

keep-positive:
: main
  (forall ρ; ρ xs:Seq Int^many -- ρ positives:Seq Int^many)
  locals { xs } {
    prim seq-int.empty
    0
    xs
    call filter-loop
  };

: filter-loop
  (forall ρ; ρ result:Seq Int^many i:Int^many xs:Seq Int^many -- ρ filtered:Seq Int^many)
  locals { result i xs } {
    i xs prim seq-int.len prim <
    [
      xs i prim seq-int.at
      locals { elem } {
        0 elem prim <
        [
          elem
          result prim seq-int.push
        ]
        [ result ]
        if
      }
      i 1 prim +
      xs
      call filter-loop
    ]
    [ result ]
    if
  };

all-true:
: main
  (forall ρ; ρ flags:Seq Bool^many -- ρ all:Bool^many)
  locals { flags } {
    1
    0
    flags
    call all-true-loop
  };

: all-true-loop
  (forall ρ; ρ result:Bool^many i:Int^many flags:Seq Bool^many -- ρ all:Bool^many)
  locals { result i flags } {
    result prim not
    [
      0
    ]
    [
      i flags prim seq-bool.len prim <
      [
        flags i prim seq-bool.at
        [
          1
          i 1 prim +
          flags
          call all-true-loop
        ]
        [ 0 ]
        if
      ]
      [ 1 ]
      if
    ]
    if
  };

count-distinct:
: main
  (forall ρ; ρ xs:Seq Int^many -- ρ count:Int^many)
  locals { xs } {
    0
    0
    xs
    call count-distinct-main
  };

: count-distinct-main
  (forall ρ; ρ count:Int^many i:Int^many xs:Seq Int^many -- ρ result:Int^many)
  locals { count i xs } {
    i xs prim seq-int.len prim <
    [
      xs i prim seq-int.at
      locals { elem } {
        0
        xs
        elem
        i
        call check-if-new
      }
      [
        count 1 prim +
      ]
      [
        count
      ]
      if
      i 1 prim +
      xs
      call count-distinct-main
    ]
    [ count ]
    if
  };

: check-if-new
  (forall ρ; ρ j:Int^many xs:Seq Int^many elem:Int^many i:Int^many -- ρ found:Bool^many)
  locals { j xs elem i } {
    j i prim <
    [
      xs j prim seq-int.at elem prim =
      [
        1
      ]
      [
        j 1 prim +
        xs
        elem
        i
        call check-if-new
      ]
      if
    ]
    [ 0 ]
    if
  };

digits:
: main
  (forall ρ; ρ n:Int^many -- ρ digits:Seq Int^many)
  locals { n } {
    prim seq-int.empty
    n
    call extract-digits-reverse
    call reverse-digits
  };

: extract-digits-reverse
  (forall ρ; ρ result:Seq Int^many n:Int^many -- ρ digits:Seq Int^many)
  locals { result n } {
    n 0 prim =
    [ result ]
    [
      n 10 prim mod
      result prim seq-int.push
      n 10 prim div
      call extract-digits-reverse
    ]
    if
  };

: reverse-digits
  (forall ρ; ρ xs:Seq Int^many -- ρ reversed:Seq Int^many)
  locals { xs } {
    prim seq-int.empty
    xs prim seq-int.len 1 prim -
    xs
    call reverse-loop
  };

: reverse-loop
  (forall ρ; ρ result:Seq Int^many i:Int^many xs:Seq Int^many -- ρ reversed:Seq Int^many)
  locals { result i xs } {
    i 0 prim <
    prim not
    [
      xs i prim seq-int.at
      result prim seq-int.push
      i 1 prim -
      xs
      call reverse-loop
    ]
    [ result ]
    if
  };

primes-up-to:
: main
  (forall ρ; ρ n:Int^many -- ρ primes:Seq Int^many)
  locals { n } {
    prim seq-int.empty
    2
    n
    call find-primes-loop
  };

: find-primes-loop
  (forall ρ; ρ result:Seq Int^many i:Int^many n:Int^many -- ρ primes:Seq Int^many)
  locals { result i n } {
    i n prim <
    [
      i
      call is-prime
      [
        i
        result prim seq-int.push
      ]
      [ result ]
      if
      i 1 prim +
      n
      call find-primes-loop
    ]
    [ result ]
    if
  };

: is-prime
  (forall ρ; ρ num:Int^many -- ρ prime:Bool^many)
  locals { num } {
    num 2 prim <
    [
      0
    ]
    [
      num 2 prim =
      [
        1
      ]
      [
        num 2 prim mod 0 prim =
        [
          0
        ]
        [
          2
          num
          call check-divisors
        ]
        if
      ]
      if
    ]
    if
  };

: check-divisors
  (forall ρ; ρ i:Int^many num:Int^many -- ρ prime:Bool^many)
  locals { i num } {
    i i prim * num prim <
    [
      num i prim mod 0 prim =
      [
        0
      ]
      [
        i 2 prim +
        num
        call check-divisors
      ]
      if
    ]
    [ 1 ]
    if
  };

sort:
: main
  (forall ρ; ρ xs:Seq Int^many -- ρ sorted:Seq Int^many)
  locals { xs } {
    prim seq-int.empty
    0
    xs
    call insertion-sort-loop
  };

: insertion-sort-loop
  (forall ρ; ρ result:Seq Int^many i:Int^many xs:Seq Int^many -- ρ sorted:Seq Int^many)
  locals { result i xs } {
    i xs prim seq-int.len prim <
    [
      xs i prim seq-int.at
      result
      0
      call insert-into-sorted
      i 1 prim +
      xs
      call insertion-sort-loop
    ]
    [ result ]
    if
  };

: insert-into-sorted
  (forall ρ; ρ elem:Int^many result:Seq Int^many pos:Int^many -- ρ inserted:Seq Int^many)
  locals { elem result pos } {
    pos result prim seq-int.len prim <
    [
      result pos prim seq-int.at elem prim <
      [
        elem
        result pos prim seq-int.set
      ]
      [
        pos 1 prim +
        call insert-into-sorted
      ]
      if
    ]
    [
      elem
      result prim seq-int.push
    ]
    if
  };

ledger:
: main
  (forall ρ; ρ start:Int^many txs:Seq Int^many -- ρ balance:Int^many rejected:Int^many)
  locals { start txs } {
    start
    0
    0
    txs
    call ledger-loop
  };

: ledger-loop
  (forall ρ; ρ balance:Int^many rejected:Int^many i:Int^many txs:Seq Int^many -- ρ final-balance:Int^many final-rejected:Int^many)
  locals { balance rejected i txs } {
    i txs prim seq-int.len prim <
    [
      txs i prim seq-int.at
      locals { tx } {
        balance tx prim + 0 prim <
        [
          balance
          rejected 1 prim +
        ]
        [
          balance tx prim +
          rejected
        ]
        if
      }
      i 1 prim +
      txs
      call ledger-loop
    ]
    [ balance rejected ]
    if
  };
